export const newKeys = { en: {}, zh: {}, fr: {}, ja: {}, ru: {}, vi: {} };
const locales = ['en', 'zh', 'fr', 'ja', 'ru', 'vi'];
const knownSources = new Set(v2SourceKeys);
for (const row of translations) {
  const key = row[0];
  if (row.length !== locales.length || !knownSources.has(key) || Object.hasOwn(newKeys.en, key)) {
    throw new Error(`Invalid or duplicate V2 translation row: ${key}`);
  }
  for (let index = 0; index < locales.length; index++) newKeys[locales[index]][key] = row[index];
}

// The source key stays stable while the rendered English fits the narrow perk card.
newKeys.en['Cannon and frost fire +1 shot. Each shot deals 13% less damage.'] = 'Cannon/Frost: +1 shot. Damage per shot -13%.';
